SELECT COALESCE(r.c_customer_sk,          r.old__c_customer_sk)::text        AS id,
       COALESCE(r.c_customer_id,          r.old__c_customer_id,         '')  AS customer_id,
       COALESCE(r.c_current_cdemo_sk,     r.old__c_current_cdemo_sk,    0)   AS current_cdemo_sk,
       COALESCE(r.c_current_hdemo_sk,     r.old__c_current_hdemo_sk,    0)   AS current_hdemo_sk,
       COALESCE(r.c_current_addr_sk,      r.old__c_current_addr_sk,     0)   AS current_addr_sk,
       COALESCE(r.c_first_shipto_date_sk, r.old__c_first_shipto_date_sk,0)   AS first_shipto_date_sk,
       COALESCE(r.c_first_sales_date_sk,  r.old__c_first_sales_date_sk, 0)   AS first_sales_date_sk,
       COALESCE(r.c_salutation,           r.old__c_salutation,          '')  AS salutation,
       COALESCE(r.c_first_name,           r.old__c_first_name,          '')  AS first_name,
       COALESCE(r.c_last_name,            r.old__c_last_name,           '')  AS last_name,
       COALESCE(r.c_preferred_cust_flag,  r.old__c_preferred_cust_flag, 'N') AS preferred_cust_flag,
       COALESCE(r.c_birth_day,            r.old__c_birth_day,           0)   AS birth_day,
       COALESCE(r.c_birth_month,          r.old__c_birth_month,         0)   AS birth_month,
       COALESCE(r.c_birth_year,           r.old__c_birth_year,          0)   AS birth_year,
       COALESCE(r.c_birth_country,        r.old__c_birth_country,       '')  AS birth_country,
       COALESCE(r.c_login,                r.old__c_login,               '')  AS login,
       COALESCE(r.c_email_address,        r.old__c_email_address,       '')  AS email_address,
       COALESCE(r.c_last_review_date_sk,  r.old__c_last_review_date_sk, 0)   AS last_review_date_sk
FROM {{ .rows }}
